tool.command:

  ln -f -s ${input_structure_path} ${input_structure_path}_`echo $$`.${input_structure_path.ext};

  ln -f -s ${input_structure_2_path} ${input_structure_2_path}_`echo $$`.${input_structure_2_path.ext};

  ln -f -s ${input_traj_path} ${input_traj_path}_`echo $$`.${input_traj_path.ext};

  ln -f -s ${input_traj_2_path} ${input_traj_2_path}_`echo $$`.${input_traj_2_path.ext};

  ln -f -s ${input_energy_path} ${input_energy_path}_`echo $$`.${input_energy_path.ext};

  ln -f -s ${input_energy_2_path} ${input_energy_2_path}_`echo $$`.${input_energy_2_path.ext};

  ln -f -s ${structure_check_path} ${structure_check_path}_`echo $$`.${structure_check_path.ext};

  ln -f -s ${input_index_path} ${input_index_path}_`echo $$`.${input_index_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

gmx_check

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__vdwfac__dq__:${properties.vdwfac},__dq__bonlo__dq__:${properties.bonlo},__dq__bonhi__dq__:${properties.bonhi},__dq__relative_tolerance__dq__:${properties.relative_tolerance},__dq__absolute_tolerance__dq__:${properties.absolute_tolerance},__dq__rmsd__dq__:${properties.rmsd},__dq__compare_ab__dq__:${properties.compare_ab},__dq__last_energy_term__dq__:__dq__${properties.last_energy_term}__dq__,__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_structure_path) != 'None':
    --input_structure_path ${input_structure_path}_`echo $$`.${input_structure_path.ext}
  #end if

  #if str($input_structure_2_path) != 'None':
    --input_structure_2_path ${input_structure_2_path}_`echo $$`.${input_structure_2_path.ext}
  #end if

  #if str($input_traj_path) != 'None':
    --input_traj_path ${input_traj_path}_`echo $$`.${input_traj_path.ext}
  #end if

  #if str($input_traj_2_path) != 'None':
    --input_traj_2_path ${input_traj_2_path}_`echo $$`.${input_traj_2_path.ext}
  #end if

  #if str($input_energy_path) != 'None':
    --input_energy_path ${input_energy_path}_`echo $$`.${input_energy_path.ext}
  #end if

  #if str($input_energy_2_path) != 'None':
    --input_energy_2_path ${input_energy_2_path}_`echo $$`.${input_energy_2_path.ext}
  #end if

  #if str($structure_check_path) != 'None':
    --structure_check_path ${structure_check_path}_`echo $$`.${structure_check_path.ext}
  #end if

  #if str($input_index_path) != 'None':
    --input_index_path ${input_index_path}_`echo $$`.${input_index_path.ext}
  #end if


  --output_log_path $outname_output_log_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_structure_path}_`echo $$`.${input_structure_path.ext};

  rm -f ${input_structure_2_path}_`echo $$`.${input_structure_2_path.ext};

  rm -f ${input_traj_path}_`echo $$`.${input_traj_path.ext};

  rm -f ${input_traj_2_path}_`echo $$`.${input_traj_2_path.ext};

  rm -f ${input_energy_path}_`echo $$`.${input_energy_path.ext};

  rm -f ${input_energy_2_path}_`echo $$`.${input_energy_2_path.ext};

  rm -f ${structure_check_path}_`echo $$`.${structure_check_path.ext};

  rm -f ${input_index_path}_`echo $$`.${input_index_path.ext};


  if test -f $outname_output_log_path; then mv $outname_output_log_path $output_log_path; fi;
